function FeatureLockedModal({ visible, feature, onClose }) {
  if (!visible || !feature) return null;

  const { authProfile } = useContext(AuthContext);
  const featureTitle = feature.title || 'Premium feature';
  const featureMessage = feature.message || 'Unlock this with PetSync+ Premium.';
  const featureBenefits = getFeatureLockedBenefits(feature.featureKey);
  const revenueCatReady = Boolean(authProfile?.revenueCatReady);
  const premiumSubscriptionActive = Boolean(
    authProfile?.revenueCatPremiumActive
    || authProfile?.premium
    || isPremiumUser(authProfile),
  );

  const handleViewPlan = () => {
    if (navigationRef.isReady()) {
      navigationRef.navigate('Settings', { openSubscription: true });
    }
    onClose?.();
  };

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <View style={s.modalOverlay}>
        <View style={[s.customActionModal, s.featureLockedModal]}>
          <ScrollView
            contentContainerStyle={{ paddingBottom: 2 }}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
          >
            <View style={s.featureLockedBadge}>
              <Text style={s.featureLockedBadgeText}>
                {revenueCatReady
                  ? (premiumSubscriptionActive ? 'Your Premium subscription is active.' : 'You\'re on the Free plan.')
                  : 'Checking your subscription...'}
              </Text>
            </View>
            <Text style={s.customActionModalTitle}>{featureTitle}</Text>
            <Text style={s.featureLockedReason}>
              {featureMessage}
            </Text>
            <View style={s.featureLockedBenefitList}>
              {featureBenefits.map((benefit) => (
                <View key={benefit} style={s.featureLockedBenefitRow}>
                  <MaterialCommunityIcons name="check-circle-outline" size={16} color={C.modalBodyText} style={s.featureLockedBullet} />
                  <Text style={s.featureLockedBenefitText}>{benefit}</Text>
                </View>
              ))}
            </View>
            <Text style={s.featureLockedFooter}>
              {premiumSubscriptionActive
                ? 'Your Premium subscription is active.'
                : 'Upgrade to access advanced pet care tools, unlimited pets, AI Vet, Family Sharing, Lost Pet SOS, and more.'}
            </Text>
          </ScrollView>
          <View style={s.customActionModalButtons}>
            <TouchableOpacity style={[s.customActionCancelBtn, s.featureLockedPrimaryBtn]} onPress={handleViewPlan}>
              <Text style={s.featureLockedPrimaryText}>View Premium Plan</Text>
            </TouchableOpacity>
            <TouchableOpacity style={s.customActionCancelBtn} onPress={onClose}>
              <Text style={s.customActionCancelText}>Close</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
}

