const DatePickerField = ({ label, value, onChange, placeholder }) => {
  const [showPicker, setShowPicker] = useState(false);
  const [tempDate, setTempDate] = useState(() => parseStoredDateKey(value) || new Date());

  useEffect(() => {
    if (showPicker) {
      setTempDate(parseStoredDateKey(value) || new Date());
    }
  }, [showPicker, value]);

  const openPicker = () => setShowPicker(true);
  const closePicker = () => setShowPicker(false);

  const confirmDate = (date) => {
    if (!date) return;
    onChange(toLocalDateKey(date));
    setShowPicker(false);
  };

  return (
    <>
      <Text style={s.datePickerLabel}>{label}</Text>
      <TouchableOpacity style={s.datePickerField} onPress={openPicker} activeOpacity={0.85}>
        <Text style={[s.datePickerFieldText, !value && s.datePickerPlaceholder]}>
          {value ? formatDate(value) : placeholder}
        </Text>
        <Text style={s.datePickerChevron}>?</Text>
      </TouchableOpacity>

      <Modal visible={showPicker} transparent animationType="fade" onRequestClose={closePicker}>
        <View style={s.datePickerOverlay}>
          <View style={s.datePickerModal}>
            <View style={s.datePickerModalHeader}>
              <Text style={s.datePickerModalTitle}>{label}</Text>
              <TouchableOpacity onPress={closePicker}>
                <Text style={s.datePickerModalClose}>?</Text>
              </TouchableOpacity>
            </View>

            <View style={s.datePickerPickerWrap}>
              <DateTimePicker
                value={tempDate}
                mode="date"
                display={Platform.OS === 'ios' ? 'spinner' : 'default'}
                onChange={(event, selectedDate) => {
                  if (Platform.OS === 'android') {
                    if (event.type === 'dismissed') {
                      closePicker();
                      return;
                    }
                    if (selectedDate) {
                      confirmDate(selectedDate);
                    }
                    return;
                  }

                  if (selectedDate) {
                    setTempDate(selectedDate);
                  }
                }}
                style={{ width: '100%' }}
                themeVariant="dark"
              />
            </View>

            <View style={s.datePickerButtons}>
              <TouchableOpacity style={s.customActionCancelBtn} onPress={closePicker}>
                <Text style={s.customActionCancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity style={s.customActionSaveBtn} onPress={() => confirmDate(tempDate)}>
                <Text style={s.customActionSaveText}>Select Date</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </>
  );
};

const ReminderTimePickerField = ({
  value,
  showPicker,
  setShowPicker,
  onChange,
}) => {
  const pickerValue = value ? parseReminderTimeToDate(value) : new Date();
  const closePicker = () => setShowPicker(false);
  const applyTime = (date) => {
    if (!date) return;
    onChange(formatTimeForReminder(date));
    setShowPicker(false);
  };

  return (
    <>
      <Text style={s.reminderModalLabel}>Reminder Time</Text>
      <TouchableOpacity
        style={s.datePickerField}
        onPress={() => {
          console.log('Reminder time field pressed');
          setShowPicker(true);
        }}
        activeOpacity={0.85}
      >
        <Text style={[s.datePickerFieldText, !normalizeReminderTimeLabel(value) && s.datePickerPlaceholder]}>
          {normalizeReminderTimeLabel(value) || 'Select time'}
        </Text>
        <Text style={s.datePickerChevron}>?</Text>
      </TouchableOpacity>
      <Text style={{ color: C.healthMutedText, fontSize: 12, marginTop: 6, fontWeight: '600' }}>
        Use AM or PM.
      </Text>

      {Platform.OS !== 'ios' && showPicker ? (
        <View style={{ marginTop: 10 }}>
          <View style={s.datePickerPickerWrap}>
            <DateTimePicker
              value={pickerValue}
              mode="time"
              display="default"
              onChange={(event, selectedDate) => {
                if (event.type === 'dismissed') {
                  closePicker();
                  return;
                }

                if (selectedDate) {
                  applyTime(selectedDate);
                }
              }}
              style={{ width: '100%' }}
              themeVariant="dark"
            />
          </View>
        </View>
      ) : null}

      <Modal
        visible={showPicker && Platform.OS === 'ios'}
        transparent
        animationType="fade"
        onRequestClose={closePicker}
      >
        <View style={s.datePickerOverlay}>
          <View style={s.datePickerModal}>
            <View style={s.datePickerModalHeader}>
              <Text style={s.datePickerModalTitle}>Select Time</Text>
              <TouchableOpacity onPress={closePicker}>
                <Text style={s.datePickerModalClose}>?</Text>
              </TouchableOpacity>
            </View>
            <View style={s.datePickerPickerWrap}>
              <DateTimePicker
                value={pickerValue}
                mode="time"
                display="spinner"
                onChange={(_, selectedDate) => {
                  if (selectedDate) {
                    onChange(formatTimeForReminder(selectedDate));
                  }
                }}
                style={{ width: '100%' }}
                themeVariant="dark"
              />
            </View>
            <View style={s.datePickerButtons}>
              <TouchableOpacity onPress={closePicker} style={s.customActionSaveBtn}>
                <Text style={s.customActionSaveText}>Done</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </>
  );
};

const addDaysLocal = (date, days) => {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
};

const formatMonthYear = (date) => date.toLocaleDateString([], { month: 'short', year: 'numeric' });

const getStreakEventsForPet = (activityLogs, petId, allowedTypes = null) => {
  const trendEvents = getTrendEventsForPet(activityLogs, petId);
  if (!Array.isArray(trendEvents) || trendEvents.length === 0) return [];

  const allowedSet = Array.isArray(allowedTypes)
    ? new Set(allowedTypes.map((type) => normalizeCareActivityType(type)))
    : null;

  const byDay = new Map();
  trendEvents.forEach((event) => {
    const eventDate = new Date(event?.created_at || event?.createdAt || event?.dateKey || 0);
    if (Number.isNaN(eventDate.getTime())) return;

    const normalizedType = normalizeCareActivityType(event?.action_type || event?.type);
    if (allowedSet && !allowedSet.has(normalizedType)) return;

    const dayKey = eventDate.toDateString();
    if (!byDay.has(dayKey)) {
      byDay.set(dayKey, {
        ...event,
        action_type: normalizedType,
        type: normalizedType,
        created_at: event?.created_at || event?.createdAt || eventDate.toISOString(),
      });
    }
  });

  return [...byDay.values()].sort((a, b) => {
    const left = new Date(a?.created_at || a?.createdAt || a?.dateKey || 0).getTime();
    const right = new Date(b?.created_at || b?.createdAt || b?.dateKey || 0).getTime();
    return right - left;
  });
};

const getStreakDaysFromEvents = (events) => {
  if (!Array.isArray(events) || events.length === 0) return 0;

  const uniqueDays = [...new Set(events.map((event) => {
    const eventDate = new Date(event?.created_at || event?.createdAt || event?.dateKey || 0);
    if (Number.isNaN(eventDate.getTime())) return null;
    return eventDate.toDateString();
  }).filter(Boolean))];

  let streakDays = 0;
  for (let i = 0; i < uniqueDays.length; i += 1) {
    const expected = new Date();
    expected.setHours(0, 0, 0, 0);
    expected.setDate(expected.getDate() - i);
    const expectedDay = expected.toDateString();
    if (uniqueDays.includes(expectedDay)) {
      streakDays += 1;
    } else {
      break;
    }
  }

  return streakDays;
};

const getStreakSummaryForPet = (activityLogs, petId) => {
  const careEvents = getStreakEventsForPet(activityLogs, petId);
  const medicationEvents = getStreakEventsForPet(activityLogs, petId, ['medication']);
  const walkEvents = getStreakEventsForPet(activityLogs, petId, ['walk']);
  const reminderEvents = getStreakEventsForPet(activityLogs, petId, ['reminder_completed']);

  return {
    care_streak: getStreakDaysFromEvents(careEvents),
    medication_streak: getStreakDaysFromEvents(medicationEvents),
    walk_streak: getStreakDaysFromEvents(walkEvents),
    reminder_completion_streak: getStreakDaysFromEvents(reminderEvents),
  };
};

const getStreakDaysForPet = (activityLogs, petId) => getStreakSummaryForPet(activityLogs, petId).care_streak;

const getTrendEventsForPet = (activityLogs, petId) => {
  if (!petId || !Array.isArray(activityLogs)) return [];

  return activityLogs
    .filter((log) => {
      const logPetId = log?.petId ?? log?.pet_id;
      const createdAt = log?.created_at || log?.createdAt || log?.dateKey;
      const normalizedType = normalizeCareActivityType(log?.type || log?.action_type);
      return String(logPetId || '') === String(petId) && !!createdAt && CARE_ACTIVITY_TYPES.has(normalizedType);
    })
    .sort((a, b) => {
      const left = new Date(a?.created_at || a?.createdAt || a?.dateKey || 0).getTime();
      const right = new Date(b?.created_at || b?.createdAt || b?.dateKey || 0).getTime();
      return right - left;
    });
};

const getWeeklyTrendService = () => createWeeklyTrendService({  });

const getWeeklyTrendSummaryForPet = (...args) =>
  getWeeklyTrendService().getWeeklyTrendSummaryForPet(...args);



const getTrendActionBreakdownForPet = (activityLogs, petId) => {
  const breakdown = {
    meal: 0,
    walk: 0,
    medication: 0,
    weight: 0,
    grooming: 0,
    vet_visit: 0,
    reminder_completed: 0,
    custom: 0,
  };

  getTrendEventsForPet(activityLogs, petId).forEach((event) => {
    const normalizedType = normalizeCareActivityType(event?.action_type || event?.type);
    if (Object.prototype.hasOwnProperty.call(breakdown, normalizedType)) {
      breakdown[normalizedType] += 1;
    } else {
      breakdown.custom += 1;
    }
  });

  return breakdown;
};

const calculateAgeLabelFromBirthday = (birthdayKey) => {
  if (!birthdayKey || !/^\d{4}-\d{2}-\d{2}$/.test(birthdayKey)) return '';

  const [year, month, day] = birthdayKey.split('-').map(Number);
  const birthDate = new Date(year, month - 1, day);
  if (Number.isNaN(birthDate.getTime())) return '';

  const today = new Date();
  let years = today.getFullYear() - birthDate.getFullYear();
  const monthDiff = today.getMonth() - birthDate.getMonth();

  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
    years -= 1;
  }

  if (years >= 1) {
    return `${years} yr${years === 1 ? '' : 's'}`;
  }

  const months = Math.max(
    1,
    (today.getFullYear() - birthDate.getFullYear()) * 12
      + (today.getMonth() - birthDate.getMonth())
      - (today.getDate() < birthDate.getDate() ? 1 : 0)
  );

  return `${months} mo${months === 1 ? '' : 's'}`;
};

